<template><main class="grid-background min-h-screen p-4 space-y-4"><HeaderStatus :connected="connected"/><div class="grid grid-cols-[30%_44%_26%] gap-4 h-[calc(100vh-5.5rem)]"><div class="space-y-4 min-h-0"><PanelFrame title="AGV STATUS"><div class="space-y-3"><AgvStatusCard v-for="a in agv.items" :key="a.agvId" :agv="a"/></div></PanelFrame><PanelFrame title="AGV CONTROL"><AgvControl :agvs="agv.items"/></PanelFrame></div><div class="space-y-4 min-h-0 flex flex-col"><PanelFrame title="MISSION QUEUE"><MissionQueue :items="mission.items"/></PanelFrame><PanelFrame title="FACTORY DIGITAL MAP" class="flex-1"><FactoryMap :markers="map.markers" :agvs="map.agvs" :marker-by-id="map.markerById"/></PanelFrame><PanelFrame title="EVENT LOG"><EventLog :items="event.items"/></PanelFrame></div><div class="space-y-4 min-h-0"><PanelFrame title="OPERATOR REQUEST"><CommandPanel/></PanelFrame><PanelFrame title="INVENTORY"><InventoryPanel :items="inventory.items"/></PanelFrame><PanelFrame title="AI RECOMMENDATION"><AiRecommendation :items="rec.items"/></PanelFrame></div></div></main></template>
<script setup>
import { onMounted, ref } from 'vue'
import HeaderStatus from '../components/layout/HeaderStatus.vue'; import PanelFrame from '../components/layout/PanelFrame.vue'; import AgvStatusCard from '../components/agv/AgvStatusCard.vue'; import AgvControl from '../components/agv/AgvControl.vue'; import MissionQueue from '../components/mission/MissionQueue.vue'; import FactoryMap from '../components/map/FactoryMap.vue'; import CommandPanel from '../components/command/CommandPanel.vue'; import InventoryPanel from '../components/inventory/InventoryPanel.vue'; import AiRecommendation from '../components/ai/AiRecommendation.vue'; import EventLog from '../components/event/EventLog.vue'
import { useAgvStore } from '../stores/agvStore'; import { useMissionStore } from '../stores/missionStore'; import { useInventoryStore } from '../stores/inventoryStore'; import { useRecommendationStore } from '../stores/recommendationStore'; import { useEventStore } from '../stores/eventStore'; import { useMapStore } from '../stores/mapStore'; import { connectDashboardSocket } from '../websocket/dashboardSocket'
const connected=ref(false), agv=useAgvStore(), mission=useMissionStore(), inventory=useInventoryStore(), rec=useRecommendationStore(), event=useEventStore(), map=useMapStore()
onMounted(async()=>{await Promise.all([agv.load(),mission.load(),inventory.load(),map.load()]); connectDashboardSocket({onOpen:()=>connected.value=true,onClose:()=>connected.value=false,onError:()=>connected.value=false,onMessage:msg=>{if(msg.type==='AGV_STATUS_UPDATED')agv.update(msg.data); if(msg.type==='MISSION_QUEUE_UPDATED')mission.setItems(msg.data); if(msg.type==='FACTORY_MAP_UPDATED')map.updateAgv(msg.data); if(msg.type==='INVENTORY_UPDATED')inventory.setItems(msg.data); if(msg.type==='EVENT_LOG_CREATED')event.push(msg.data); if(msg.type==='AI_RECOMMENDATION_UPDATED')rec.setItems(msg.data)}})})
</script>
